"""Writes slice13e-seed.sql: members, requests, comments and view logs for the administrator list comparison (WBS 7.2.9).

It is loaded after seed.sql and slice13d-seed.sql. Every list that the original sorts by created_at has distinct timestamps, so the
order does not depend on how the database breaks ties. Usage: python3 slice13e_make_seed.py
"""
from pathlib import Path

FIXTURE = Path(__file__).resolve().parent.parent
ALICE = "11111111-1111-4111-8111-111111111111"


def uid(prefix, n):
    return f"{prefix}-0000-4000-8000-{n:012d}"


def stamp(month, day, second):
    return f"'2026-{month:02d}-{day:02d} 09:{second // 60:02d}:{second % 60:02d}'"


def sql():
    out = ["-- Administrator list rows on top of seed.sql and slice13d-seed.sql. Generated by reference/slice13e_make_seed.py."]
    users = []
    for n in range(1, 26):
        role = "ADMIN" if n % 9 == 0 else "GENERAL"
        deleted = 1 if n % 7 == 0 else 0
        users.append(f" ('{uid('66666666', n)}', 'member{n}@example.com', 'pbkdf2:hash-{n}', '회원{n}', '{role}', {n % 4 or 'NULL'}, "
                     f"{n % 2}, {1 - n % 2}, {deleted}, {stamp(3, n, n)}, {stamp(3, n, n)})")
    out.append("INSERT INTO `user` (user_id, email, password, name, role, profile_image_id, is_tutorial_done, is_verify_email_done, is_deleted, created_at, updated_at) VALUES")
    out.append(",\n".join(users) + ";")
    members = [uid("66666666", n) for n in range(1, 26)]
    comments = []
    videos = [uid("bbbbbbbb", n) for n in (1, 2, 3, 4, 8, 9, 14, 19)] + ["aaaaaaaa-0000-4000-8000-000000000001", "aaaaaaaa-0000-4000-8000-000000000003"]
    for n in range(1, 41):
        comments.append(f" ('{uid('cccccccc', 100 + n)}', '{videos[n % len(videos)]}', '{members[n % 25]}', '관리자 목록 댓글 {n} {'맛집' if n % 5 == 0 else '일상'}', "
                        f"{n % 2}, {1 if n % 6 == 0 else 0}, {stamp(4, n % 28 + 1, n)}, {stamp(4, n % 28 + 1, n)})")
    out.append("INSERT INTO comment (comment_id, video_id, user_id, content, is_modified, is_deleted, created_at, updated_at) VALUES")
    out.append(",\n".join(comments) + ";")
    requests = []
    for n in range(1, 31):
        status = ["PENDING", "ACCEPTED", "REJECTED"][n % 3]
        note = "NULL" if status == "PENDING" else f"'처리 {n}'"
        requests.append(f" ('{uid('ffffffff', 100 + n)}', '{members[n % 25]}', 'req{n:08d}', 'https://www.youtube.com/watch?v=req{n:08d}', '{status}', {note}, "
                        f"{stamp(5, n % 28 + 1, n)}, {stamp(5, n % 28 + 1, n + 1)})")
    out.append("INSERT INTO video_request (video_request_id, user_id, youtube_url, youtube_full_url, status, admin_comment, created_at, updated_at) VALUES")
    out.append(",\n".join(requests) + ";")
    logs = []
    for n in range(1, 61):
        user = members[n % 25] if n % 4 else "NULL"
        user = user if user == "NULL" else f"'{user}'"
        guest = "'guest-" + str(n) + "'" if user == "NULL" else "NULL"
        logs.append(f" ('{uid('99999999', 200 + n)}', '{videos[n % len(videos)]}', {user}, {guest}, {stamp(6, n % 28 + 1, n)}, {stamp(6, n % 28 + 1, n)})")
    out.append("INSERT INTO video_view_log (video_view_log_id, video_id, user_id, guest_token, created_at, updated_at) VALUES")
    out.append(",\n".join(logs) + ";")
    out.append(f"INSERT INTO video_like (video_like_id, video_id, user_id, created_at) VALUES ('{uid('dddddddd', 900)}', '{uid('bbbbbbbb', 1)}', '{members[3]}', '2026-06-01 00:00:00');")
    return "\n".join(out) + "\n"


if __name__ == "__main__":
    (FIXTURE / "slice13e-seed.sql").write_text(sql())
